from pathlib import Path
import base64, zlib, os, subprocess

root = Path(__file__).resolve().parents[2]
FILES = {
    'src/main/java/com/crispywafer/crispywaferguntracker/GunTrackerConfigScreen.java': '',
    'src/main/resources/assets/crispywaferguntrackermod/lang/zh_cn.json': '',
    'src/main/resources/assets/crispywaferguntrackermod/lang/en_us.json': '',
}
for rel, data in FILES.items():
    path = root / rel
    path.write_bytes(zlib.decompress(base64.b64decode(data)))
Path(__file__).unlink()
subprocess.run(["git","config","user.name","github-actions[bot]"], check=True)
subprocess.run(["git","config","user.email","41898282+github-actions[bot]@users.noreply.github.com"], check=True)
subprocess.run(["git","add",
    "src/main/java/com/crispywafer/crispywaferguntracker/GunTrackerConfigScreen.java",
    "src/main/resources/assets/crispywaferguntrackermod/lang/zh_cn.json",
    "src/main/resources/assets/crispywaferguntrackermod/lang/en_us.json",
    ".github/scripts/apply_task4_ui.py"
], check=True)
subprocess.run(["git","commit","-m","feat: expose stable lock settings in game"], check=True)
